def split_lowerstring(text):
    """Write a function to split a string at lowercase letters.

    Split ``text`` immediately before each lowercase letter. Each
    resulting piece therefore starts with a lowercase letter and
    contains any following non-lowercase characters. Characters
    before the first lowercase letter are omitted, matching the
    example ``split_lowerstring("AbCd") == ['bC', 'd']``.
    """
    parts = []
    current = ""
    for char in text:
        if char.islower():
            if current:
                parts.append(current)
            current = char
        elif current:
            current += char
    if current:
        parts.append(current)
    return parts
